fn layout(title: &str, body: &str) -> String { format!(r##"<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Amigo — مساحة تعليمية تساعدك على التعلم حسب كليتك."><title>{} | Amigo</title><link rel="icon" type="image/svg+xml" href="/static/favicon.svg"><meta name="theme-color" content="#173b32"><meta property="og:type" content="website"><meta property="og:site_name" content="Amigo"><meta property="og:title" content="{} | Amigo"><meta property="og:description" content="Amigo — مساحة تعليمية تساعدك على التعلم حسب كليتك."><meta property="og:url" content="https://amigo-gilt-nine.vercel.app/"><meta property="og:image" content="https://amigo-gilt-nine.vercel.app/static/hero-student.png"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/static/style.css?v=7"><script src="/static/app.js" defer></script><script type="module" src="/static/catalog.js?v=5"></script><script type="module" src="/static/firebase-auth.js"></script><script src="/static/i18n-dict.js?v=5" defer></script><script src="/static/i18n.js?v=6" defer></script></head><body><div class="demo-notice">نسخة تجريبية: الكليات والكورسات المعروضة أمثلة توضيحية</div><header class="header"><div class="nav wrap"><a href="/" class="logo"><span class="logo-mark">a<span>.</span></span> amigo<span class="logo-dot">.</span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="nav-links">القائمة ☰</button><nav id="nav-links" class="nav-links" aria-label="القائمة الرئيسية"><a href="/faculties">الكليات</a><a href="/courses">الكورسات</a><a href="/shared">كورسات مشتركة</a><a href="/pricing">الخطط</a><a href="/all-pages">كل الصفحات</a></nav><div class="nav-actions"><button id="lang-toggle" class="login" type="button">EN</button><a href="/login" class="login">دخول</a><a href="/register" class="btn btn-dark small">ابدأ التعلّم <span>↖</span></a></div></div></header><main>{}</main><footer><div class="wrap footer-grid"><div><a class="logo footer-logo" href="/">amigo<span>.</span></a><p>تعلّم بطريقتك، وخطّط لمستقبلك خطوة بخطوة.</p></div><div><strong>تصفّح</strong><a href="/faculties">الكليات</a><a href="/courses">كل الكورسات</a><a href="/shared">الكورسات المشتركة</a></div><div><strong>عن المنصة</strong><a href="/about">من نحن</a><a href="/pricing">الخطط</a><a href="/faq">الأسئلة الشائعة</a></div><div><strong>معلومات</strong><a href="/terms">الشروط والأحكام</a><a href="/privacy">الخصوصية</a><a href="/refund">الاسترجاع والإلغاء</a><a href="/contact">تواصل معنا</a></div></div><div class="wrap footer-bottom">© Amigo · نسخة تجريبية <span>معاك في كل خطوة ✳</span></div></footer></body></html>"##,title,title,body) }
fn hero_small(kicker:&str,title:&str,desc:&str)->String { format!(r#"<section class="page-hero"><div class="wrap"><div class="eyebrow">✳ &nbsp; {}</div><h1>{}</h1><p>{}</p></div></section>"#,kicker,title,desc) }
fn home()->String { format!(r##"<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="hero-kicker"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.1 7.9L22 12l-7.9 2.1L12 22l-2.1-7.9L2 12l7.9-2.1z"/></svg> مستقبلك يبدأ بخطوة</span><h1>تعلّم بطريقتك<br><span>مع <em>أميجو.</em></span></h1><p>للطالب طريقه، وللي خلّص واشتغل طريقه: كورسات دراسية حسب كليتك، وكورسات مهنية عملية تطوّر بيها شغلك. رحلتك في التعلّم تبدأ من هنا.</p><div class="hero-actions"><a class="btn btn-orange" href="/courses">ابدأ التعلّم <span>←</span></a><a class="text-link" href="/faculties">تصفّح الكليات <span>←</span></a></div><div class="hero-note"><span class="note-icon"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.1 7.9L22 12l-7.9 2.1L12 22l-2.1-7.9L2 12l7.9-2.1z"/></svg></span> مساحة تتعلّم فيها على راحتك</div></div><div class="hero-visual" aria-hidden="true"><div class="hero-circle"></div><div class="hero-arch"></div><div class="hero-sun"></div><span class="hero-spark hero-spark-one"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.1 7.9L22 12l-7.9 2.1L12 22l-2.1-7.9L2 12l7.9-2.1z"/></svg></span><span class="hero-spark hero-spark-two"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l2.1 7.9L22 12l-7.9 2.1L12 22l-2.1-7.9L2 12l7.9-2.1z"/></svg></span><img src="/static/hero-student.png" alt="" class="hero-student" width="1536" height="1024" fetchpriority="high"></div></div></section><section class="trust-wrap wrap" aria-label="مميزات المنصة"><div class="trust-strip"><div><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 7v14"/><path d="M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3-3 3 3 0 0 0-3 3z"/></svg></span><strong>كورسات حسب كليتك</strong></div><div><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 14 4-4"/><path d="M3.34 19a10 10 0 1 1 17.32 0"/></svg></span><strong>تعلّم بالسرعة المناسبة لك</strong></div><div><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/><path d="m22 17.65-9.17 4.16a2 2 0 0 1-1.66 0L2 17.65"/><path d="m22 12.65-9.17 4.16a2 2 0 0 1-1.66 0L2 12.65"/></svg></span><strong>مهارات مشتركة للجميع</strong></div><div><span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/></svg></span><strong>رحلتك في مكان واحد</strong></div></div></section><section class="section wrap audiences"><div class="section-head"><div><div class="eyebrow">مين يتعلم معانا؟</div><h2>مساران… <span>هدفان مختلفان.</span></h2><p>الطالب غير اللي خلّص واشتغل؛ عشان كده Amigo عنده مسار لكل واحد فيهم.</p></div></div><div class="aud-grid"><article class="aud-card"><div class="aud-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21.42 10.92a1 1 0 0 0-.02-1.84L12.83 5.18a2 2 0 0 0-1.66 0L2.6 9.08a1 1 0 0 0 0 1.84l8.57 3.91a2 2 0 0 0 1.66 0z"/><path d="M22 10v6"/><path d="M6 12.5V16a6 3 0 0 0 12 0v-3.5"/></svg></div><h3>للطلاب</h3><p>كورسات مرتبطة بكليتك وفرقتك وفصلك الدراسي، تمشّي بيك في دراستك خطوة بخطوة لحد التخرج.</p><a class="btn btn-dark" href="/courses?audience=students">كورسات الطلاب <span>←</span></a></article><article class="aud-card pro"><div class="aud-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect width="20" height="14" x="2" y="7" rx="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg></div><h3>للمحترفين والخريجين</h3><p>خلّصت واشتغلت؟ كورسات مهنية قصيرة وعملية تطوّر مهاراتك وتفتح لك فرص أكبر في شغلك — من غير فرقة ولا فصل دراسي.</p><a class="btn btn-orange" href="/courses?audience=professionals">الكورسات المهنية <span>←</span></a></article></div></section><section class="section wrap home-section"><div class="section-head"><div><div class="eyebrow">اكتشف مسارك</div><h2>الكليات <span>اللي تجمعنا.</span></h2><p>اختر كليتك وتعرّف على الكورسات المناسبة لك.</p></div><a class="arrow-link" href="/faculties">عرض كل الكليات ←</a></div><div class="faculty-grid"><div id="home-faculties" class="contents-grid"><div class="skel skel-fac"></div><div class="skel skel-fac"></div><div class="skel skel-fac"></div><div class="skel skel-fac"></div></div></div></section><section class="section featured"><div class="wrap home-section"><div class="section-head"><div><div class="eyebrow">ابدأ من هنا</div><h2>تعلّم حاجة <span>جديدة.</span></h2><p>اكتشف الكورسات المناسبة لك وطوّر مهاراتك خطوة بخطوة.</p></div><a class="arrow-link" href="/courses">عرض كل الكورسات ←</a></div><div class="course-grid"><div id="home-courses" class="contents-grid"><div class="skel skel-card"></div><div class="skel skel-card"></div><div class="skel skel-card"></div></div></div></div></section><section class="section wrap testimonials"><div class="section-head"><div><div class="eyebrow">قالوا عن أميجو</div><h2>طلابنا وخريجونا <span>بيقولوا إيه؟</span></h2></div></div><div class="testi-grid"><figure class="testi-card"><div class="testi-stars"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg></div><blockquote>كنت تايهة بين المحاضرات والملازم، أميجو جمّع لي كورسات كليتي في مكان واحد، وبقيت أذاكر بخطة واضحة بدل العشوائية.</blockquote><figcaption><span class="testi-avatar av-a">م</span><span><strong>منة خالد</strong><small>طالبة، كلية التجارة</small></span></figcaption></figure><figure class="testi-card"><div class="testi-stars"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg></div><blockquote>الكورسات المهنية فرقت معايا فعلًا؛ خلّصت كورس تحليل البيانات وطبّقت اللي اتعلمته في شغلي من أول أسبوع.</blockquote><figcaption><span class="testi-avatar av-b">ع</span><span><strong>عمر سامي</strong><small>خريج، محاسب</small></span></figcaption></figure><figure class="testi-card"><div class="testi-stars"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01z"/></svg></div><blockquote>أكتر حاجة عجبتني إن الشرح بالعربي وبأسلوب بسيط، وأقدر أرجع للدرس في أي وقت، خصوصًا قبل الامتحانات.</blockquote><figcaption><span class="testi-avatar av-c">س</span><span><strong>سارة محمود</strong><small>طالبة، كلية العلاج الطبيعي</small></span></figcaption></figure></div></section><section class="section wrap"><div class="shared-banner"><div><div class="eyebrow light">معرفة تجمعنا ✳</div><h2>مهارات مشتركة.<br><em>فرص بلا حدود.</em></h2><p>اكتشف الكورسات المشتركة بين الكليات واتعلّم مع غيرك.</p><a class="btn btn-white" href="/shared">استكشف المشترك <span>←</span></a></div><div class="banner-symbol" aria-hidden="true">✳</div></div></section>"##) }
fn catalog(is_shared:bool)->String { let title=if is_shared {"نتعلّم مع بعض."}else{"اكتشف اللي يناسبك."}; let desc=if is_shared {"كورسات واحدة تجمع طلاب أكثر من كلية، ومهارات تنفعك أينما كانت وجهتك."}else{"كورسات دراسية للطلاب حسب الكلية، وكورسات مهنية عملية للي خلّصوا ودخلوا سوق العمل."}; let content=format!(r#"{}<section class="section wrap catalog" data-shared-only="{}"><div class="aud-tabs" role="group" aria-label="الجمهور"><button type="button" class="aud-tab active" data-audience="">الكل</button><button type="button" class="aud-tab" data-audience="students">للطلاب</button><button type="button" class="aud-tab" data-audience="professionals">للمحترفين</button></div><div class="filters"><label class="search-field"><span>⌕</span><input id="search" type="search" placeholder="ابحث عن كورس..." aria-label="ابحث عن كورس"></label><label><span class="sr-only">الكلية</span><select id="faculty-filter"><option value="">كل الكليات</option></select></label><label><span class="sr-only">نوع الكورس</span><select id="shared-filter"><option value="">كل الأنواع</option><option value="true">مشترك</option><option value="false">تخصصي</option></select></label><label><span class="sr-only">المستوى</span><select id="level-filter"><option value="">كل المستويات</option></select></label><label><span class="sr-only">اللغة</span><select id="language-filter"><option value="">كل اللغات</option></select></label><label><span class="sr-only">المحاضر</span><select id="teacher-filter"><option value="">كل المحاضرين</option></select></label><button id="reset-filters" class="reset" type="button">مسح الفلاتر</button></div><div class="results-head"><strong><span id="result-count"></span> كورسات</strong></div><p id="catalog-message" class="loading" role="status">جاري تحميل الكورسات…</p><div class="course-grid" id="course-grid"></div></section>"#,hero_small(if is_shared {"نتشارك المعرفة"}else{"كل الكورسات"},title,desc),is_shared); content }
fn faculty_page()->String { format!(r#"{}<section class="section wrap"><div id="faculty-detail" role="status"><div class="loading-block"><span class="spinner"></span>جاري تحميل بيانات الكلية…</div></div></section>"#,hero_small("كليتك هنا","تفاصيل الكلية","استكشف الكورسات المرتبطة بهذه الكلية.")) }
fn course_page()->String { format!(r#"{}<section class="section wrap"><div id="course-detail" role="status"><div class="loading-block"><span class="spinner"></span>جاري تحميل بيانات الكورس…</div></div></section>"#,hero_small("الكورسات","تفاصيل الكورس","تعرّف على محتوى الكورس والكليات المرتبطة.")) }

fn pricing()->String { format!(r#"{}<section class="section wrap"><div class="pricing-grid"><article class="plan"><span>01 / لكلية واحدة</span><h2>اشتراك كلية</h2><p>كل كورسات كلية واحدة، بالإضافة للكورسات المشتركة.</p><div class="plan-price">السعر قريبًا</div><a href="/register" class="btn btn-outline full">ابدأ من هنا ←</a></article><article class="plan highlighted"><span>02 / لكل اهتماماتك</span><h2>اشتراك شامل</h2><p>استكشف كل الكورسات في كل الكليات والكورسات المشتركة.</p><div class="plan-price">السعر قريبًا</div><a href="/register" class="btn btn-orange full">ابدأ من هنا ←</a></article><article class="plan"><span>03 / على راحتك</span><h2>كورس منفرد</h2><p>اختار كورس واحد يناسب هدفك وتعلّم بالسرعة اللي تناسبك.</p><div class="plan-price">السعر قريبًا</div><a href="/courses" class="btn btn-outline full">استكشف الكورسات ←</a></article></div><p class="pricing-note">الخطط والأسعار توضيحية، والدفع غير مفعّل بعد. الكورسات المشتركة مدرجة في خطتي الكلية والشاملة؛ شراء كورس منفرد يتيح الكورس المختار فقط.</p></section>"#,hero_small("خطتك، اختيارك","تعلّم بالطريقة اللي تناسبك.","اختيارات مرنة تساعدك تبدأ من المكان المناسب لك.")) }
fn info(title:&str,body:&str)->String { format!("{}<section class=\"section wrap prose\">{}</section>",hero_small("Amigo",title,"مساحة للتعلّم بخطوات أقرب إلى هدفك."),body) }
fn blog()->String { format!("{}<section class=\"section wrap\"><div class=\"blog-grid\"><article class=\"post-card\"><span class=\"badge\">نصائح دراسية</span><h3>إزاي تذاكر بذكاء قبل الامتحانات: خطة ٧ أيام</h3><p>أسبوع واحد ممكن يفرق جدًا لو اتقسم صح: مراجعة مركزة، وحل امتحانات، ونوم كفاية.</p><small>٤ نوفمبر ٢٠٢٦ · قراءة ٣ دقائق</small><details><summary>اقرأ المقال</summary><p>ابدأ بجرد سريع: اكتب كل الموضوعات المطلوبة وقسّمها على الأيام، وخلي أول يومين لأصعب جزء وأنت لسه نشيط.</p><p>ذاكر بجلسات قصيرة مركزة (٢٥–٥٠ دقيقة) وبينها بريك قصير، وبعد كل جلسة اكتب من ذاكرتك أهم ٣ نقاط اتعلمتها.</p><p>من اليوم الرابع ابدأ حل امتحانات سابقة بوقت حقيقي، وصحّح أخطاءك وراجع الجزء اللي وقع منك بس؛ دي أسرع طريقة تثبت المعلومة.</p><p>وآخر يوم يكون خفيف: مرور سريع على الملخصات ونوم بدري. المعلومة بتتخزن وقت النوم، فمتضحيش بيه مهما حصل.</p></details></article><article class=\"post-card\"><span class=\"badge\">مهارات مهنية</span><h3>مهارات تفرق في أول شغل بعد التخرج</h3><p>الشهادة بتفتح الباب، لكن اللي بيخليك تكمل وتترقى مهارات عملية ممكن تبدأ فيها من دلوقتي.</p><small>٢ نوفمبر ٢٠٢٦ · قراءة ٣ دقائق</small><details><summary>اقرأ المقال</summary><p>أول مهارة: التعامل مع البيانات والجداول الإلكترونية. أي شغل النهاردة فيه أرقام وتقارير، واللي بيعرف ينظمها ويطلع منها معنى بيبان بسرعة.</p><p>تاني مهارة: التواصل الكتابي الواضح؛ إيميل قصير مظبوط أو تقرير صفحة واحدة بيوفروا اجتماعات كاملة وبيبنوا صورتك المهنية من أول يوم.</p><p>تالت مهارة: الإنجليزية العملية في مجالك؛ مش مطلوب طلاقة أدبية، مطلوب تقرأ مصادر تخصصك وتكتب بيها بثقة. ابدأ بكورس مهني واحد وطبّقه فورًا في شغل حقيقي ولو تطوعي.</p></details></article><article class=\"post-card\"><span class=\"badge\">تعلّم</span><h3>العربي ولا الإنجليزي؟ تتعلم بأي لغة أسرع</h3><p>إجابة السؤال ده بتتغير حسب المادة وهدفك؛ خلينا نفككها ببساطة.</p><small>٣٠ أكتوبر ٢٠٢٦ · قراءة ٣ دقائق</small><details><summary>اقرأ المقال</summary><p>لما المادة جديدة وصعبة، التعلّم بلغتك الأم بيكون أسرع وأعمق؛ لأن مجهودك بيروح للفهم مش لترجمة الكلمات. عشان كده مواد كتير عندنا شرحها بالعربي.</p><p>لكن مصادر أغلب التخصصات الحديثة مكتوبة بالإنجليزية أصلًا، والتعلم بالإنجليزية بيبني مصطلحات مجالك صح وبيفتح لك مصادر أوسع وفرص عمل أكبر.</p><p>الخلاصة العملية: ابدأ بالعربي لو الأساس مهزوز، وانتقل تدريجيًا للإنجليزية كل ما أساسك يثبت، وكورساتنا مكتوب على كل واحدة لغتها عشان تختار على بينة.</p></details></article></div></section>",hero_small("المدونة والمصادر","مقالات تساعدك تتعلّم أحسن.","نصايح دراسية ومهارات مهنية وأفكار عن التعلّم نفسه.")) }
fn profile_inputs() -> String { r#"<label>الاسم الكامل<input name="name" required minlength="2" maxlength="100" autocomplete="name"></label><label>الكلية<select name="faculty" required disabled><option value="">جاري تحميل الكليات…</option></select></label><label>الفرقة<select name="year" required><option value="">اختر الفرقة</option><option value="1">الأولى</option><option value="2">الثانية</option><option value="3">الثالثة</option><option value="4">الرابعة</option></select></label>"#.to_owned() }

fn auth(register:bool)->String { if register { format!(r#"{}<section class="section wrap"><div class="form-card"><h2>أنشئ حسابك.</h2><p>سجّل بياناتك لاختيار الكورسات المناسبة لك.</p><form id="register-form" method="post">{}<label>البريد الإلكتروني<input type="email" name="email" required autocomplete="email" dir="ltr"></label><label>كلمة المرور<input type="password" name="password" required minlength="8" autocomplete="new-password" dir="ltr"></label><label>تأكيد كلمة المرور<input type="password" name="confirm" required minlength="8" autocomplete="new-password" dir="ltr"></label><p class="form-message" role="status" aria-live="polite"></p><button class="btn btn-dark full" type="submit">إنشاء الحساب ←</button></form><p>عندك حساب؟ <a class="arrow-link" href="/login">سجّل الدخول</a></p></div></section>"#,hero_small("ابدأ رحلتك","خلّينا نبدأ مع بعض.","أنشئ حسابًا واختر كليتك وفرقتك."),profile_inputs()) } else {format!(r#"{}<section class="section wrap"><div class="form-card"><h2>أهلًا بعودتك.</h2><form id="login-form" method="post"><label>البريد الإلكتروني<input type="email" name="email" required autocomplete="email" dir="ltr"></label><label>كلمة المرور<input type="password" name="password" required autocomplete="current-password" dir="ltr"></label><p class="form-message" role="status" aria-live="polite"></p><button class="btn btn-dark full" type="submit">تسجيل الدخول ←</button></form><p><a class="arrow-link" href="/reset-password">نسيت كلمة المرور؟</a></p><p>معندكش حساب؟ <a class="arrow-link" href="/register">أنشئ حسابًا</a></p></div></section>"#,hero_small("أهلًا بيك","كمّل رحلتك.","سجّل دخولك للوصول إلى مساحتك."))} }
fn reset_password()->String {format!(r#"{}<section class="section wrap"><div class="form-card"><h2>استعادة كلمة المرور.</h2><p>أدخل بريدك وسنرسل رابط الاستعادة إذا كان الحساب متاحًا.</p><form id="reset-form" method="post"><label>البريد الإلكتروني<input type="email" name="email" required autocomplete="email" dir="ltr"></label><p class="form-message" role="status" aria-live="polite"></p><button class="btn btn-dark full" type="submit">إرسال رابط الاستعادة ←</button></form><p><a class="arrow-link" href="/login">العودة لتسجيل الدخول</a></p></div></section>"#,hero_small("حسابك","خلّينا نساعدك ترجع.","استعد الوصول إلى حسابك بأمان."))}
fn profile()->String {format!(r#"{}<section class="section wrap"><div class="form-card"><h2>بياناتك الدراسية.</h2><p>عدّل بياناتك لحفظ التوصيات المناسبة لك.</p><p id="auth-message" role="status" aria-live="polite">جاري التحقق من الحساب…</p><form id="profile-form" hidden>{}<p class="form-message" role="status" aria-live="polite"></p><button class="btn btn-dark full" type="submit">حفظ البيانات ←</button></form><p><a href="/dashboard">العودة للوحة الطالب</a></p></div></section>"#,hero_small("حسابك","ملفك الشخصي.","بياناتك مرتبطة بحسابك على Amigo."),profile_inputs())}
fn dashboard()->String { format!(r#"{}<section class="section wrap"><div class="dashboard-note"><p id="profile-summary" role="status" aria-live="polite">جاري التحقق من الحساب…</p><a href="/student/profile">تعديل البيانات ←</a></div><div id="dashboard-content" hidden><h2>كورسات قد تناسبك</h2><p>التوصيات لا تعني أنك مسجّل في الكورس.</p><div class="course-grid" id="recommendations"></div><p id="recommendations-empty" hidden>لا توجد كورسات مطابقة حاليًا.</p><button class="btn btn-outline" id="logout-button" type="button">تسجيل الخروج</button></div></section>"#,hero_small("مساحتك","أهلًا بيك في Amigo.","كل رحلة كبيرة تبدأ بخطوة صغيرة.")) }
